CREATE OR REPLACE FUNCTION public.admin_assign_question_tag(p_question_id text, p_item_number smallint, p_tag_code text, p_tag_value text DEFAULT NULL::text)
 RETURNS bigint
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare
  caller_id       uuid := auth.uid();
  v_tag           public.topik_writing_tag_master%rowtype;
  v_exists        boolean;
  v_assignment_id bigint;
  v_assigned_by   text;
begin
  if caller_id is null then raise exception 'unauthenticated'; end if;
  if not private.is_content_admin(caller_id) then
    raise exception 'forbidden: content_admin required';
  end if;
  if p_item_number not in (51, 52, 53, 54) then
    raise exception 'item_number must be one of 51/52/53/54';
  end if;

  select * into v_tag from public.topik_writing_tag_master where tag_code = p_tag_code;
  if not found then raise exception 'unknown tag_code: %', p_tag_code; end if;
  if not v_tag.is_active then raise exception 'tag is inactive: %', p_tag_code; end if;
  if v_tag.tag_group = '서비스_노출상태' then
    raise exception 'exposure-status tag group is blocked: use service_status column (D-6)';
  end if;

  execute format('select exists(select 1 from public.%I where question_id = $1)',
                 format('topik_writing_%s_questions', p_item_number))
    into v_exists using p_question_id;
  if not v_exists then raise exception 'question not found: % (item %)', p_question_id, p_item_number; end if;

  select coalesce(display_name, id::text) into v_assigned_by from public.profiles where id = caller_id;

  begin
    insert into public.topik_writing_question_tags
      (question_id, item_number, tag_code, tag_value, assigned_by)
    values (p_question_id, p_item_number, p_tag_code, p_tag_value, v_assigned_by)
    returning tag_assignment_id into v_assignment_id;
  exception when unique_violation then
    raise exception 'tag already active on this question: %', p_tag_code;
  end;

  insert into public.admin_audit_logs (admin_user_id, action, target_table, target_id, diff, payload)
  values (
    caller_id, 'tag_assigned', 'AssessmentQuestion', p_question_id,
    jsonb_build_object('tag', jsonb_build_object('from', null, 'to', p_tag_code),
                       'tag_value', jsonb_build_object('from', null, 'to', p_tag_value)),
    '{}'::jsonb
  );

  return v_assignment_id;
end;
$function$

CREATE OR REPLACE FUNCTION public.admin_cancel_notification_dispatch(p_dispatch_id uuid, p_reason text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare
  caller_id uuid := auth.uid();
  v_status  text;
  v_key     text;
begin
  if caller_id is null then raise exception 'unauthenticated'; end if;
  if not private.is_admin(caller_id) then raise exception 'forbidden: admin required'; end if;
  if nullif(btrim(coalesce(p_reason, '')), '') is null then
    raise exception 'reason required (operational reason)';
  end if;

  select status, template_key into v_status, v_key
    from public.notification_dispatches
   where id = p_dispatch_id;
  if not found then raise exception 'unknown dispatch'; end if;
  if v_status <> 'scheduled' then
    raise exception 'only scheduled dispatches can be canceled (status=%)', v_status;
  end if;

  update public.notification_dispatches
     set status = 'canceled', completed_at = now()
   where id = p_dispatch_id;

  insert into public.admin_audit_logs (admin_user_id, action, target_table, target_id, payload)
  values (caller_id, 'notification_dispatch_canceled', 'Notification', p_dispatch_id::text,
          jsonb_build_object('reason', p_reason, 'template_key', v_key));
end;
$function$

CREATE OR REPLACE FUNCTION public.admin_delete_notification_group(p_id uuid, p_reason text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare
  caller_id uuid := auth.uid();
  v_name    text;
begin
  if caller_id is null then raise exception 'unauthenticated'; end if;
  if not private.is_admin(caller_id) then raise exception 'forbidden: admin required'; end if;
  if nullif(btrim(coalesce(p_reason, '')), '') is null then
    raise exception 'reason required (operational reason)';
  end if;

  delete from public.notification_groups where id = p_id returning name into v_name;
  if v_name is null then raise exception 'unknown group id: %', p_id; end if;

  insert into public.admin_audit_logs (admin_user_id, action, target_table, target_id, payload)
  values (caller_id, 'notification_group_deleted', 'Notification', p_id::text,
          jsonb_build_object('reason', p_reason, 'name', v_name));
end;
$function$

